import React, { forwardRef, useEffect, useRef } from 'react';

import { body } from './HiveTooltip.sty.js';
import { mergeTooltipActions } from '../../core/components/series-action/functions/mergeTooltipActions.js';
import { useChartActionsMenu } from '../../core/components/series-action/hooks/useChartActionsMenu.js';
import { ChartTooltip } from '../../core/components/tooltip/ChartTooltip/ChartTooltip.js';
import { TooltipPointIndicator } from '../../core/components/tooltip/section-components/atoms/TooltipPointIndicator.js';
import { TooltipBody } from '../../core/components/tooltip/section-components/TooltipBody.js';
import { TooltipInfoContent } from '../../core/components/tooltip/section-components/TooltipInfoContent.js';
import { TooltipItem } from '../../core/components/tooltip/section-components/TooltipItem.js';
import { TooltipValueContent } from '../../core/components/tooltip/section-components/TooltipValueContent.js';
import { useTooltipSeriesActions } from '../../core/components/tooltip/shared/hooks/useTooltipSeriesActions.js';
import { safeGet } from '../../core/functions/safe-get.js';
import { getMetadataMap } from '../functions/tooltip-helpers.js';
import { useHoneycombColorMetadata } from '../hooks/use-honeycomb-color-metadata.js';
import { useHoneycombData } from '../hooks/use-honeycomb-data.js';
import {
  useHoneycombOverlayMouseInBoundsState,
  useHoneycombTooltipPinnedState,
  useHoneycombTooltipState,
} from '../store/selectors.js';
import { HoneycombTileMetaData } from '../types/honeycomb-internal.js';
import { HoneycombTileData } from '../types/honeycomb.js';

export const HiveTooltip = forwardRef<HTMLDivElement>((_, forwardedRef) => {
  const { enabled, visible, tileData, position } = useHoneycombTooltipState();
  const tooltipItem = useRef<HoneycombTileMetaData>({
    id: '',
    name: '',
    value: '',
    color: { Default: '' },
  });
  const pinned = useHoneycombTooltipPinnedState();
  const mouseInBounds = useHoneycombOverlayMouseInBoundsState();
  const { colorMetadata } = useHoneycombColorMetadata();
  const {
    selectedItem: selectedItemId,
    actionsMenuRef,
    updateSelectedItem,
    onLeave,
  } = useChartActionsMenu();
  const honeycombData = useHoneycombData();
  const metadataMap = getMetadataMap(honeycombData, colorMetadata);

  const seriesActions = useTooltipSeriesActions<HoneycombTileData>(
    honeycombData,
    (tileData) => safeGet(metadataMap, tileData).id,
  );

  const honeycombActionsCallback = mergeTooltipActions(
    tooltipItem.current,
    seriesActions,
  );

  useEffect(() => {
    if (!pinned) {
      updateSelectedItem('');
    }
  }, [pinned, updateSelectedItem]);

  const forceHideTooltip = !pinned && (!mouseInBounds || !visible);

  if (!enabled || forceHideTooltip || !position) {
    return null;
  }

  if (!pinned && tileData) {
    // while tooltip is pinned, we don't update current tooltip information
    tooltipItem.current = safeGet(metadataMap, tileData);
  }

  return (
    <ChartTooltip
      position={position}
      pinned={pinned}
      onMouseLeave={onLeave}
      ref={forwardedRef}
      actionSelectionValue={{
        selectedItemId,
        actionsMenuRef,
        updateSelectedItem,
      }}
    >
      <TooltipBody className={body} virtualization={false}>
        <TooltipItem actions={honeycombActionsCallback}>
          <TooltipPointIndicator color={tooltipItem.current.color.Default} />
          <TooltipInfoContent>{tooltipItem.current.name}</TooltipInfoContent>
          <TooltipValueContent variant="chip">
            {tooltipItem.current.value}
          </TooltipValueContent>
        </TooltipItem>
      </TooltipBody>
    </ChartTooltip>
  );
});

HiveTooltip['displayName'] = 'HiveTooltip';
